output_text:
[
  {
    "id": "must_take_entry_cart",
    "text": "A shopper is obliged to take the entrance cart before completing the trip.",
    "abstraction": {
      "state_properties": {
        "at_entry_cart_station": {
          "and": [
            "at(1,5)",
            "cartAt(1,5)"
          ]
        },
        "has_shopping_cart": "hasCart"
      },
      "events": {
        "pickup_entry_cart": {
          "pre": {
            "and": [
              "at_entry_cart_station",
              "PICKUP_CART"
            ]
          },
          "post": "has_shopping_cart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "pickup_entry_cart"
    }
  },
  {
    "id": "pickup_items_only_with_cart",
    "text": "A shopper is prohibited from picking up shelf items unless they are currently pushing or holding a cart.",
    "abstraction": {
      "state_properties": {
        "cart_controlled": "hasCart",
        "without_cart": {
          "not": "hasCart"
        }
      },
      "events": {
        "cartless_item_pickup": {
          "pre": {
            "and": [
              "without_cart",
              "PICKUP_ITEM"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "cartless_item_pickup"
    }
  },
  {
    "id": "no_hand_carrying",
    "text": "A shopper is prohibited from carrying merchandise by hand rather than putting it in the cart.",
    "abstraction": {
      "state_properties": {
        "carrying_by_hand": "handFull",
        "cart_available_or_used": {
          "or": [
            "hasCart",
            "cartAt(0,1)",
            "cartAt(1,5)"
          ]
        }
      },
      "events": {
        "becomes_hand_full": {
          "pre": "PICKUP_ITEM",
          "post": "carrying_by_hand"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "carrying_by_hand"
    }
  },
  {
    "id": "return_cart_after_shopping",
    "text": "After taking any required item, the shopper is obliged to return the cart to the designated cart-return cell before the trajectory ends.",
    "abstraction": {
      "state_properties": {
        "cart_return_cell": "at(0,1)",
        "cart_parked_in_return": "cartAt(0,1)",
        "shopping_with_cart": "hasCart"
      },
      "events": {
        "take_shelf_item": {
          "pre": "PICKUP_ITEM",
          "post": null
        },
        "return_cart_to_bay": {
          "pre": {
            "and": [
              "shopping_with_cart",
              "cart_return_cell",
              "LEAVE_CART"
            ]
          },
          "post": "cart_parked_in_return"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "take_shelf_item",
      "discharge": "return_cart_to_bay"
    }
  },
  {
    "id": "leave_cart_only_at_return_bay",
    "text": "A shopper is prohibited from leaving the cart anywhere other than the official return bay at cell (0,1).",
    "abstraction": {
      "state_properties": {
        "official_cart_return_bay": "at(0,1)",
        "not_at_cart_return_bay": {
          "not": "official_cart_return_bay"
        }
      },
      "events": {
        "abandon_cart_outside_bay": {
          "pre": {
            "and": [
              "LEAVE_CART",
              "not_at_cart_return_bay"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "abandon_cart_outside_bay"
    }
  },
  {
    "id": "exit_without_cart_after_checkin",
    "text": "A shopper is prohibited from exiting while still possessing the cart or before the cart is parked in the return bay.",
    "abstraction": {
      "state_properties": {
        "cart_checked_in": "cartAt(0,1)",
        "cart_not_checked_in": {
          "not": "cart_checked_in"
        },
        "still_with_cart": "hasCart",
        "bad_exit_cart_status": {
          "or": [
            "still_with_cart",
            "cart_not_checked_in"
          ]
        }
      },
      "events": {
        "exit_with_unreturned_cart": {
          "pre": {
            "and": [
              "EXIT",
              "bad_exit_cart_status"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "exit_with_unreturned_cart"
    }
  },
  {
    "id": "no_more_interactions_after_cart_return",
    "text": "Once the cart is parked in the return bay, the shopper is prohibited from performing further store interactions.",
    "abstraction": {
      "state_properties": {
        "cart_already_returned": "cartAt(0,1)",
        "pedestrian_phase": {
          "and": [
            "cart_already_returned",
            {
              "not": "hasCart"
            }
          ]
        }
      },
      "events": {
        "post_return_interaction": {
          "pre": {
            "and": [
              "pedestrian_phase",
              "INTERACT"
            ]
          },
          "post": null
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "post_return_interaction"
    }
  },
  {
    "id": "must_drop_cart_at_return_not_drive_away",
    "text": "When the shopper reaches the cart-return cell while still possessing the cart, they are prohibited from moving away instead of leaving the cart there.",
    "abstraction": {
      "state_properties": {
        "at_cart_return_cell": "at(0,1)",
        "arrived_with_cart_at_return": {
          "and": [
            "at_cart_return_cell",
            "hasCart"
          ]
        }
      },
      "events": {
        "move_away_with_cart_from_return": {
          "pre": {
            "and": [
              "arrived_with_cart_at_return",
              "MOVE"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": "move_away_with_cart_from_return"
    }
  }
]
